"use client";
import { Workout } from "@/types/Workout";
import { useContext } from "react";
import { WorkoutContext } from "@/context/WorkoutContext";
import Button from "@/components/shared/Button-1";
import { toast } from "react-toastify";
import Image from "next/image";
import addicon from "@/assets/add-icon.png"

interface AddToPlanButtonProps {
    workout: Workout;
}

const AddToPlanButton = ({ workout }: AddToPlanButtonProps) => {
    const { planWorkouts, setPlanWorkouts } = useContext(WorkoutContext);
    const handleAddToPlan = () => {
        const alreadyAdded = planWorkouts.some(
            (item) => item.id === workout.id
        );
        if (alreadyAdded) {
            toast.info("Already added to today's plan");
            return;
        }

        setPlanWorkouts([...planWorkouts, workout]);
        toast.success("Added to today's plan");
    };
    return (
        <Button
            onClick={handleAddToPlan}
            disabled={planWorkouts.length >= 5} className="mx-auto lg:mx-0"> <Image src={addicon} alt="Add" width={18} height={18} /> Add to today's plan
        </Button>
    );
};

export default AddToPlanButton;

"use client";
import { Workout } from "@/types/Workout";
import { useContext } from "react";
import { WorkoutContext } from "@/context/WorkoutContext";
import Button2 from "@/components/shared/Button-2";
import SaveIcon from "@/assets/save-icon.png"
import Image from "next/image";
import { toast } from "react-toastify";

interface SaveButtonProps {
    workout: Workout;
}

const SaveButton = ({ workout }: SaveButtonProps) => {
    const { savedWorkouts, setSavedWorkouts } = useContext(WorkoutContext);
    const handleSave = () => {
        const alreadySaved = savedWorkouts.some(
            (item) => item.id === workout.id
        );
        if (alreadySaved) {
            toast.info("Already saved");
            return;
        }
        setSavedWorkouts([...savedWorkouts, workout]);
        toast.success("Saved for later");
    };
    return (
        <Button2 onClick={handleSave} className="w-52 mx-auto lg:mx-0">
            <Image
                src={SaveIcon}
                alt="Save"
                width={20}
                height={20}
                className="brightness-0 invert"
            />
            Save for later
        </Button2>
    );
};

export default SaveButton;

"use client";
import { Workout } from "@/types/Workout";
import React, { createContext, ReactNode, useState } from "react";

interface IWorkoutContext {
    planWorkouts: Workout[];
    setPlanWorkouts: React.Dispatch<React.SetStateAction<Workout[]>>;
    savedWorkouts: Workout[];
    setSavedWorkouts: React.Dispatch<React.SetStateAction<Workout[]>>;
}

export const WorkoutContext = createContext<IWorkoutContext>({
    planWorkouts: [],
    setPlanWorkouts: () => { },
    savedWorkouts: [],
    setSavedWorkouts: () => { },
});

const WorkoutProvider = ({ children }: { children: ReactNode }) => {
    const [planWorkouts, setPlanWorkouts] = useState<Workout[]>([]);
    const [savedWorkouts, setSavedWorkouts] = useState<Workout[]>([]);

    const sharedData = {
        planWorkouts,
        setPlanWorkouts,
        savedWorkouts,
        setSavedWorkouts,
    };

    return (
        <WorkoutContext.Provider value={sharedData}>
            {children}
        </WorkoutContext.Provider>
    );

};

export default WorkoutProvider;

export interface Workout {
    id: number;
    name: string;
    image: string;
    muscleGroups: string[];
    equipment: string;
    difficulty: string;
    duration: number;
    caloriesBurned: number;
    sets: number;
    reps: number;
    rating: number;
    description: string;
    instructions: string[];
}
